 if ( ! defined( 'ABSPATH' ) ) { exit; } function hvm_logo_link( $attachment_id ) { $attachment_id = absint( $attachment_id ); return array( 'url' => (string) get_post_meta( $attachment_id, '_hvm_logo_url', true ), 'blank' => '1' === (string) get_post_meta( $attachment_id, '_hvm_logo_blank', true ), ); } add_filter( 'attachment_fields_to_edit', function ( $fields, $post ) { if ( ! $post instanceof WP_Post ) { return $fields; } $url = get_post_meta( $post->ID, '_hvm_logo_url', true ); $blank = '1' === (string) get_post_meta( $post->ID, '_hvm_logo_blank', true ); $fields['hvm_logo_url'] = array( 'label' => 'Logo Link URL', 'input' => 'text', 'value' => $url, 'helps' => 'Where this logo links to when used in a Logo Grid (leave empty for no link).', ); $fields['hvm_logo_blank'] = array( 'label' => 'Open in new tab', 'input' => 'html', 'html' => sprintf( '<label style="display:inline-flex;gap:6px;align-items:center;"><input type="checkbox" name="attachments[%1$d][hvm_logo_blank]" value="1" %2$s /> Open this logo link in a new tab</label>', (int) $post->ID, checked( $blank, true, false ) ), ); return $fields; }, 10, 2 ); add_filter( 'attachment_fields_to_save', function ( $post, $attachment ) { if ( array_key_exists( 'hvm_logo_url', $attachment ) ) { $clean = esc_url_raw( trim( (string) $attachment['hvm_logo_url'] ) ); if ( '' === $clean ) { delete_post_meta( $post['ID'], '_hvm_logo_url' ); } else { update_post_meta( $post['ID'], '_hvm_logo_url', $clean ); } if ( ! empty( $attachment['hvm_logo_blank'] ) ) { update_post_meta( $post['ID'], '_hvm_logo_blank', '1' ); } else { delete_post_meta( $post['ID'], '_hvm_logo_blank' ); } } return $post; }, 10, 2 ); 